package com.hostelfind.service;
import com.hostelfind.dto.ClaimRequest; import com.hostelfind.model.*; import com.hostelfind.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class ClaimService { private final ClaimRepository claims; private final ItemRepository items; private final UserRepository users; public ClaimService(ClaimRepository c,ItemRepository i,UserRepository u){claims=c;items=i;users=u;} public Claim create(ClaimRequest r){Item item=items.findById(r.itemId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Item not found"));if(item.getStatus()!=ItemStatus.OPEN)throw new ResponseStatusException(HttpStatus.CONFLICT,"Item is not open for claims");Claim c=new Claim();c.setItem(item);c.setClaimant(users.findById(r.claimantId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid claimantId")));c.setProofOrMessage(r.proofOrMessage());item.setStatus(ItemStatus.CLAIMED);items.save(item);return claims.save(c);} public List<Claim> forItem(Long itemId){return claims.findByItemId(itemId);} public Claim update(Long id,ClaimStatus status){Claim c=claims.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Claim not found"));c.setStatus(status);if(status==ClaimStatus.APPROVED){Item i=c.getItem();i.setStatus(ItemStatus.RETURNED);items.save(i);}return claims.save(c);} }
